/* GlobalStone — Corporate Site Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:wght@400;500;600;700&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --navy: #0A1628;
  --navy-light: #132039;
  --navy-mid: #1a2d4a;
  --forest: #003F2D;
  --teal: #012A2D;
  --gold: #C9A96E;
  --gold-light: #D4BA8A;
  --gold-dark: #B8944F;
  --gray-50: #F8F9FA;
  --gray-100: #F1F3F5;
  --gray-200: #E6E6E6;
  --gray-300: #DEE2E6;
  --gray-400: #ADB5BD;
  --gray-500: #868E96;
  --gray-600: #6C757D;
  --gray-700: #495057;
  --gray-800: #343A40;
  --white: #FFFFFF;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'Playfair Display', Georgia, serif;
  --max-width: 1280px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { text-decoration: none; color: inherit; transition: color var(--transition); }
img { max-width: 100%; display: block; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
@media (min-width: 768px) { .container { padding: 0 40px; } }
@media (min-width: 1024px) { .container { padding: 0 64px; } }

/* ===================== HEADER / NAV ===================== */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: var(--navy);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  transition: background var(--transition), box-shadow var(--transition);
}
.site-header.scrolled { box-shadow: 0 4px 24px rgba(0,0,0,0.3); }
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto;
  padding: 0 24px; height: 72px;
}
@media (min-width: 768px) { .header-inner { padding: 0 40px; } }
@media (min-width: 1024px) { .header-inner { padding: 0 64px; height: 80px; } }

.logo {
  font-family: var(--font-heading); font-size: 1.5rem; font-weight: 700;
  color: var(--white); letter-spacing: 0.5px;
  display: flex; align-items: center; gap: 10px;
}
.logo-icon {
  width: 36px; height: 36px; background: var(--gold);
  border-radius: 4px; display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-weight: 700; color: var(--navy);
  font-size: 1.1rem;
}

/* Desktop Nav */
.desktop-nav { display: none; }
@media (min-width: 1024px) { .desktop-nav { display: flex; align-items: center; gap: 32px; } }
.desktop-nav a {
  color: rgba(255,255,255,0.85); font-size: 0.9rem; font-weight: 500;
  letter-spacing: 0.3px; padding: 8px 0;
  position: relative; transition: color var(--transition);
}
.desktop-nav a::after {
  content: ''; position: absolute; bottom: 0; left: 0; width: 0; height: 2px;
  background: var(--gold); transition: width var(--transition);
}
.desktop-nav a:hover { color: var(--white); }
.desktop-nav a:hover::after { width: 100%; }

.nav-services-trigger { cursor: pointer; position: relative; }
.nav-services-trigger .chevron {
  display: inline-block; margin-left: 4px; transition: transform var(--transition);
  font-size: 0.7rem;
}
.nav-services-trigger.active .chevron { transform: rotate(180deg); }

/* Mega Menu */
.mega-menu {
  position: absolute; top: 100%; left: 0; right: 0;
  background: var(--navy-light);
  border-top: 1px solid rgba(255,255,255,0.06);
  box-shadow: 0 16px 48px rgba(0,0,0,0.4);
  opacity: 0; visibility: hidden; transform: translateY(-8px);
  transition: all var(--transition);
}
.mega-menu.open { opacity: 1; visibility: visible; transform: translateY(0); }
.mega-menu-inner {
  max-width: var(--max-width); margin: 0 auto;
  padding: 40px 64px; display: grid;
  grid-template-columns: 1fr 1fr; gap: 48px;
}
.mega-menu-col h4 {
  font-size: 0.75rem; font-weight: 600; text-transform: uppercase;
  letter-spacing: 1.5px; color: var(--gold);
  margin-bottom: 20px; padding-bottom: 12px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.mega-menu-col ul { display: flex; flex-direction: column; gap: 6px; }
.mega-menu-col a {
  display: block; padding: 10px 16px; border-radius: 6px;
  color: rgba(255,255,255,0.8); font-size: 0.9rem; font-weight: 400;
  transition: all var(--transition);
}
.mega-menu-col a:hover {
  background: rgba(255,255,255,0.06); color: var(--white);
  padding-left: 20px;
}
.mega-menu-col a::after { display: none; }

/* Hamburger */
.hamburger {
  display: flex; flex-direction: column; gap: 5px;
  width: 28px; padding: 4px 0; z-index: 1001;
}
@media (min-width: 1024px) { .hamburger { display: none; } }
.hamburger span {
  display: block; height: 2px; background: var(--white);
  border-radius: 2px; transition: all var(--transition);
}
.hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* Mobile Nav */
.mobile-nav {
  position: fixed; top: 72px; left: 0; right: 0; bottom: 0;
  background: var(--navy); z-index: 999;
  transform: translateX(100%); transition: transform var(--transition);
  overflow-y: auto; padding: 24px;
}
.mobile-nav.open { transform: translateX(0); }
.mobile-nav > a, .mobile-accordion-trigger {
  display: block; padding: 16px 0;
  color: var(--white); font-size: 1.1rem; font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  width: 100%; text-align: left;
}
.mobile-accordion-trigger {
  display: flex; justify-content: space-between; align-items: center;
}
.mobile-accordion-trigger .chevron {
  transition: transform var(--transition); font-size: 0.8rem; color: var(--gold);
}
.mobile-accordion-trigger.active .chevron { transform: rotate(180deg); }
.mobile-accordion-content {
  max-height: 0; overflow: hidden;
  transition: max-height 0.4s ease;
}
.mobile-accordion-content.open { max-height: 600px; }
.mobile-accordion-content a {
  display: block; padding: 12px 0 12px 20px;
  color: rgba(255,255,255,0.7); font-size: 0.95rem;
  border-bottom: 1px solid rgba(255,255,255,0.04);
}
.mobile-accordion-content a:hover { color: var(--gold); }
.mobile-accordion-content h5 {
  font-size: 0.7rem; font-weight: 600; text-transform: uppercase;
  letter-spacing: 1.5px; color: var(--gold);
  padding: 16px 0 8px 20px;
}

/* ===================== HERO ===================== */
.hero {
  position: relative; min-height: 85vh;
  display: flex; align-items: center;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 40%, var(--teal) 100%);
  overflow: hidden; margin-top: 72px;
}
@media (min-width: 1024px) { .hero { margin-top: 80px; min-height: 90vh; } }
.hero-bg-pattern {
  position: absolute; inset: 0; opacity: 0.06;
  background-image:
    radial-gradient(circle at 20% 80%, rgba(201,169,110,0.3) 0%, transparent 50%),
    radial-gradient(circle at 80% 20%, rgba(201,169,110,0.2) 0%, transparent 50%),
    linear-gradient(45deg, transparent 48%, rgba(255,255,255,0.03) 49%, rgba(255,255,255,0.03) 51%, transparent 52%);
  background-size: 100% 100%, 100% 100%, 60px 60px;
}
.hero-content { position: relative; z-index: 2; padding: 80px 0; }
.hero-label {
  display: inline-block; font-size: 0.75rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 2px; color: var(--gold);
  margin-bottom: 24px; padding: 6px 16px;
  border: 1px solid rgba(201,169,110,0.3); border-radius: 4px;
}
.hero h1 {
  font-family: var(--font-heading); font-size: clamp(2.2rem, 5vw, 3.8rem);
  font-weight: 600; color: var(--white); line-height: 1.15;
  max-width: 700px; margin-bottom: 24px;
}
.hero p {
  font-size: clamp(1rem, 1.5vw, 1.2rem);
  color: rgba(255,255,255,0.75); max-width: 560px;
  line-height: 1.7; margin-bottom: 36px;
}
.hero-stats {
  display: flex; gap: 48px; margin-top: 48px;
  padding-top: 32px; border-top: 1px solid rgba(255,255,255,0.1);
}
.hero-stat-number {
  font-family: var(--font-heading); font-size: 2.5rem;
  font-weight: 700; color: var(--gold);
}
.hero-stat-label { font-size: 0.85rem; color: rgba(255,255,255,0.6); margin-top: 4px; }

/* Page Hero (smaller variant for inner pages) */
.page-hero {
  position: relative; padding: 140px 0 80px;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 50%, var(--teal) 100%);
  margin-top: 72px;
}
@media (min-width: 1024px) { .page-hero { padding: 160px 0 100px; margin-top: 80px; } }
.page-hero .hero-bg-pattern { position: absolute; inset: 0; opacity: 0.06;
  background-image: radial-gradient(circle at 20% 80%, rgba(201,169,110,0.3) 0%, transparent 50%),
  radial-gradient(circle at 80% 20%, rgba(201,169,110,0.2) 0%, transparent 50%);
}
.page-hero-content { position: relative; z-index: 2; }
.page-hero h1 {
  font-family: var(--font-heading); font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 600; color: var(--white); line-height: 1.2;
  max-width: 700px; margin-bottom: 20px;
}
.page-hero p {
  font-size: clamp(1rem, 1.3vw, 1.15rem);
  color: rgba(255,255,255,0.7); max-width: 600px; line-height: 1.7;
}
.breadcrumbs {
  display: flex; align-items: center; gap: 8px;
  margin-bottom: 24px; font-size: 0.85rem;
}
.breadcrumbs a { color: rgba(255,255,255,0.5); }
.breadcrumbs a:hover { color: var(--gold); }
.breadcrumbs span { color: rgba(255,255,255,0.3); }
.breadcrumbs .current { color: rgba(255,255,255,0.8); }

/* ===================== BUTTONS ===================== */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 14px 32px; font-size: 0.9rem; font-weight: 600;
  border-radius: 4px; letter-spacing: 0.3px;
  transition: all var(--transition);
}
.btn-primary {
  background: var(--gold); color: var(--navy);
}
.btn-primary:hover { background: var(--gold-light); transform: translateY(-1px); box-shadow: 0 4px 16px rgba(201,169,110,0.3); }
.btn-outline {
  border: 1.5px solid rgba(255,255,255,0.3); color: var(--white);
}
.btn-outline:hover { border-color: var(--gold); color: var(--gold); }
.btn-dark {
  background: var(--navy); color: var(--white);
}
.btn-dark:hover { background: var(--navy-light); }
.btn-ghost {
  color: var(--gold); font-weight: 600; padding: 0;
}
.btn-ghost:hover { color: var(--gold-light); }
.btn-ghost .arrow { transition: transform var(--transition); }
.btn-ghost:hover .arrow { transform: translateX(4px); }

/* ===================== SECTIONS ===================== */
.section { padding: 80px 0; }
@media (min-width: 1024px) { .section { padding: 100px 0; } }
.section-dark { background: var(--navy); color: var(--white); }
.section-light { background: var(--gray-50); }
.section-label {
  font-size: 0.75rem; font-weight: 600; text-transform: uppercase;
  letter-spacing: 2px; color: var(--gold); margin-bottom: 16px;
}
.section-title {
  font-family: var(--font-heading); font-size: clamp(1.8rem, 3vw, 2.6rem);
  font-weight: 600; line-height: 1.2; margin-bottom: 20px;
}
.section-subtitle {
  font-size: 1.05rem; color: var(--gray-600); line-height: 1.7;
  max-width: 640px;
}
.section-dark .section-subtitle { color: rgba(255,255,255,0.65); }

/* ===================== FEATURED INSIGHTS ===================== */
.featured-insights { padding: 80px 0; background: var(--white); }
@media (min-width: 1024px) { .featured-insights { padding: 100px 0; } }
.insights-grid {
  display: grid; gap: 24px;
  grid-template-columns: 1fr;
}
@media (min-width: 768px) { .insights-grid { grid-template-columns: repeat(3, 1fr); } }
.insight-card {
  background: var(--white); border-radius: 8px; overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.insight-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.1); border-color: transparent; }
.insight-card-image {
  height: 200px; background: linear-gradient(135deg, var(--navy) 0%, var(--teal) 100%);
  position: relative; overflow: hidden;
}
.insight-card-image .overlay-icon {
  position: absolute; bottom: 16px; left: 16px;
  background: rgba(255,255,255,0.15); backdrop-filter: blur(8px);
  border-radius: 50%; width: 40px; height: 40px;
  display: flex; align-items: center; justify-content: center;
  color: var(--white); font-size: 0.8rem;
}
.insight-card-body { padding: 24px; }
.insight-card-tag {
  font-size: 0.7rem; font-weight: 600; text-transform: uppercase;
  letter-spacing: 1.5px; color: var(--gold); margin-bottom: 12px;
}
.insight-card-body h3 {
  font-size: 1.05rem; font-weight: 600; color: var(--gray-800);
  line-height: 1.4; margin-bottom: 16px;
}
.insight-card-body .read-more {
  font-size: 0.85rem; font-weight: 600; color: var(--forest);
  display: inline-flex; align-items: center; gap: 6px;
}
.insight-card-body .read-more:hover { color: var(--gold); }

/* ===================== ANNOUNCEMENT BANNER ===================== */
.announcement {
  background: var(--forest); padding: 20px 0;
}
.announcement-inner {
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 16px;
}
.announcement p { color: var(--white); font-size: 1rem; font-weight: 500; }
.announcement .btn { padding: 10px 24px; font-size: 0.85rem; }

/* ===================== ABOUT STATEMENT ===================== */
.about-statement { padding: 100px 0; background: var(--white); }
@media (min-width: 1024px) { .about-statement { padding: 120px 0; } }
.about-inner {
  display: grid; gap: 48px; align-items: center;
}
@media (min-width: 1024px) { .about-inner { grid-template-columns: 1fr 1fr; gap: 80px; } }
.about-text .section-title { margin-bottom: 24px; }
.about-text p { color: var(--gray-600); line-height: 1.8; margin-bottom: 32px; }
.about-visual {
  height: 400px; border-radius: 8px; overflow: hidden;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 50%, var(--teal) 100%);
  position: relative;
}
.about-visual::after {
  content: ''; position: absolute; inset: 0;
  background: repeating-linear-gradient(
    90deg, transparent 0, transparent 39px,
    rgba(255,255,255,0.03) 39px, rgba(255,255,255,0.03) 40px
  );
}

/* ===================== WHAT WE DO (TABS) ===================== */
.what-we-do { padding: 100px 0; background: var(--navy); }
@media (min-width: 1024px) { .what-we-do { padding: 120px 0; } }
.tabs-container {
  display: grid; gap: 32px; margin-top: 48px;
}
@media (min-width: 768px) { .tabs-container { grid-template-columns: 280px 1fr; gap: 48px; } }
.tab-list { display: flex; flex-direction: column; gap: 4px; }
.tab-button {
  text-align: left; padding: 18px 24px;
  font-size: 1rem; font-weight: 500;
  color: rgba(255,255,255,0.5);
  border-left: 3px solid rgba(255,255,255,0.1);
  transition: all var(--transition);
  border-radius: 0 6px 6px 0;
}
.tab-button:hover { color: rgba(255,255,255,0.8); background: rgba(255,255,255,0.03); }
.tab-button.active {
  color: var(--white); border-left-color: var(--gold);
  background: rgba(255,255,255,0.05);
}
.tab-panel { display: none; animation: fadeIn 0.4s ease; }
.tab-panel.active { display: block; }
.tab-panel h3 {
  font-family: var(--font-heading); font-size: 1.8rem;
  font-weight: 600; color: var(--white); margin-bottom: 20px;
}
.tab-panel p {
  color: rgba(255,255,255,0.7); line-height: 1.8;
  margin-bottom: 32px; font-size: 1.05rem;
}
.tab-panel .services-list {
  margin-bottom: 32px;
}
.tab-panel .services-list li {
  padding: 8px 0; color: rgba(255,255,255,0.6); font-size: 0.95rem;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  display: flex; align-items: center; gap: 12px;
}
.tab-panel .services-list li::before {
  content: ''; width: 6px; height: 6px; border-radius: 50%;
  background: var(--gold); flex-shrink: 0;
}
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===================== NEWSLETTER ===================== */
.newsletter {
  padding: 80px 0;
  background: linear-gradient(135deg, var(--forest) 0%, var(--teal) 100%);
}
.newsletter-inner { text-align: center; max-width: 560px; margin: 0 auto; }
.newsletter h2 {
  font-family: var(--font-heading); font-size: clamp(1.6rem, 3vw, 2.2rem);
  color: var(--white); margin-bottom: 16px;
}
.newsletter p { color: rgba(255,255,255,0.7); margin-bottom: 32px; font-size: 1.05rem; }
.newsletter-form { display: flex; gap: 12px; max-width: 480px; margin: 0 auto; }
.newsletter-form input {
  flex: 1; padding: 14px 20px; border-radius: 4px;
  border: 1px solid rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.1); color: var(--white);
  font-size: 0.95rem; font-family: var(--font-body);
  outline: none; transition: border-color var(--transition);
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.4); }
.newsletter-form input:focus { border-color: var(--gold); }
@media (max-width: 480px) {
  .newsletter-form { flex-direction: column; }
}

/* ===================== LATEST INSIGHTS ===================== */
.latest-insights { padding: 100px 0; background: var(--gray-50); }
.latest-grid {
  display: grid; gap: 24px; margin-top: 48px;
}
@media (min-width: 768px) { .latest-grid { grid-template-columns: repeat(3, 1fr); } }
.latest-card {
  background: var(--white); border-radius: 8px; overflow: hidden;
  border: 1px solid var(--gray-200); transition: all var(--transition);
}
.latest-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
.latest-card-image {
  height: 180px; position: relative;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
}
.latest-card-image .card-tag {
  position: absolute; top: 16px; left: 16px;
  background: var(--gold); color: var(--navy);
  font-size: 0.7rem; font-weight: 600; text-transform: uppercase;
  letter-spacing: 1px; padding: 4px 12px; border-radius: 3px;
}
.latest-card-body { padding: 24px; }
.latest-card-body .meta {
  font-size: 0.8rem; color: var(--gray-500); margin-bottom: 10px;
}
.latest-card-body h3 {
  font-size: 1rem; font-weight: 600; line-height: 1.4;
  color: var(--gray-800); margin-bottom: 16px;
}
.latest-card-body .read-link {
  font-size: 0.85rem; font-weight: 600; color: var(--forest);
  display: inline-flex; align-items: center; gap: 6px;
}
.latest-card-body .read-link:hover { color: var(--gold); }

/* ===================== COMMITMENT ===================== */
.commitment { padding: 100px 0; background: var(--white); }
.commitment-grid {
  display: grid; gap: 24px; margin-top: 48px;
}
@media (min-width: 768px) { .commitment-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1024px) { .commitment-grid { grid-template-columns: repeat(4, 1fr); } }
.commitment-card {
  padding: 32px; border-radius: 8px;
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.commitment-card:hover { border-color: var(--gold); transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.06); }
.commitment-card-icon {
  width: 48px; height: 48px; border-radius: 8px;
  background: linear-gradient(135deg, var(--navy) 0%, var(--teal) 100%);
  display: flex; align-items: center; justify-content: center;
  color: var(--gold); font-size: 1.2rem; margin-bottom: 20px;
}
.commitment-card h3 { font-size: 1.1rem; font-weight: 600; margin-bottom: 12px; color: var(--gray-800); }
.commitment-card p { font-size: 0.9rem; color: var(--gray-600); line-height: 1.6; margin-bottom: 20px; }

/* ===================== SERVICES GRID ===================== */
.services-grid {
  display: grid; gap: 24px; margin-top: 48px;
}
@media (min-width: 768px) { .services-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1024px) { .services-grid { grid-template-columns: repeat(3, 1fr); } }
.service-card {
  background: var(--white); border-radius: 8px; padding: 40px 32px;
  border: 1px solid var(--gray-200);
  transition: all var(--transition); position: relative; overflow: hidden;
}
.service-card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0;
  height: 3px; background: var(--gold); transform: scaleX(0);
  transform-origin: left; transition: transform var(--transition);
}
.service-card:hover { transform: translateY(-4px); box-shadow: 0 16px 48px rgba(0,0,0,0.08); }
.service-card:hover::before { transform: scaleX(1); }
.service-card-icon {
  width: 56px; height: 56px; border-radius: 10px;
  background: var(--gray-50); display: flex;
  align-items: center; justify-content: center;
  color: var(--forest); font-size: 1.5rem; margin-bottom: 24px;
}
.service-card h3 { font-size: 1.2rem; font-weight: 600; margin-bottom: 14px; color: var(--gray-800); }
