  --gold-light: #D4BA8A;
  --gold-dark: #B8944F;
  --gray-50: #F8F9FA;
  --gray-100: #F1F3F5;
  --gray-200: #E6E6E6;
  --gray-300: #DEE2E6;
  --gray-400: #ADB5BD;
  --gray-500: #868E96;
  --gray-600: #6C757D;
  --gray-700: #495057;
  --gray-800: #343A40;
  --white: #FFFFFF;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'Playfair Display', Georgia, serif;
  --max-width: 1280px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { text-decoration: none; color: inherit; transition: color var(--transition); }
img { max-width: 100%; display: block; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
@media (min-width: 768px) { .container { padding: 0 40px; } }
@media (min-width: 1024px) { .container { padding: 0 64px; } }

/* ===================== HEADER / NAV ===================== */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: var(--navy);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  transition: background var(--transition), box-shadow var(--transition);
}
.site-header.scrolled { box-shadow: 0 4px 24px rgba(0,0,0,0.3); }
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto;
  padding: 0 24px; height: 72px;
}
@media (min-width: 768px) { .header-inner { padding: 0 40px; } }
@media (min-width: 1024px) { .header-inner { padding: 0 64px; height: 80px; } }

.logo {
  font-family: var(--font-heading); font-size: 1.5rem; font-weight: 700;
  color: var(--white); letter-spacing: 0.5px;
  display: flex; align-items: center; gap: 10px;
}
.logo-icon {
  width: 36px; height: 36px; background: var(--gold);
  border-radius: 4px; display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-weight: 700; color: var(--navy);
  font-size: 1.1rem;
}

/* Desktop Nav */
.desktop-nav { display: none; }
@media (min-width: 1024px) { .desktop-nav { display: flex; align-items: center; gap: 32px; } }
.desktop-nav a {
  color: rgba(255,255,255,0.85); font-size: 0.9rem; font-weight: 500;
  letter-spacing: 0.3px; padding: 8px 0;
  position: relative; transition: color var(--transition);
}
.desktop-nav a::after {
  content: ''; position: absolute; bottom: 0; left: 0; width: 0; height: 2px;
  background: var(--gold); transition: width var(--transition);
}
.desktop-nav a:hover { color: var(--white); }
.desktop-nav a:hover::after { width: 100%; }

.nav-services-trigger { cursor: pointer; position: relative; }
.nav-services-trigger .chevron {
  display: inline-block; margin-left: 4px; transition: transform var(--transition);
  font-size: 0.7rem;
}
.nav-services-trigger.active .chevron { transform: rotate(180deg); }

/* Mega Menu */
.mega-menu {
  position: absolute; top: 100%; left: 0; right: 0;
  background: var(--navy-light);
  border-top: 1px solid rgba(255,255,255,0.06);
