}
.related-card h4 { font-size: 1rem; font-weight: 600; margin-bottom: 6px; }
.related-card p { font-size: 0.85rem; color: var(--gray-600); line-height: 1.5; }

/* ===================== DEAL FLOW CTA ===================== */
.deal-flow-cta {
