}
.property-card:hover { border-color: var(--gold); transform: translateY(-2px); }
.property-card .icon { font-size: 1.8rem; margin-bottom: 12px; }
.property-card h4 { font-size: 0.95rem; font-weight: 600; color: var(--gray-800); }

/* ===================== INTRO STATEMENT ===================== */
.intro-statement { padding: 80px 0; background: var(--white); }
.intro-inner { max-width: 800px; }
.intro-inner h2 {
  font-family: var(--font-heading); font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 600; color: var(--navy); margin-bottom: 20px; line-height: 1.3;
}
.intro-inner p { font-size: 1.05rem; color: var(--gray-600); line-height: 1.8; }

/* ===================== FOOTER ===================== */
.site-footer {
